def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'D'

    opp_moves = [h[1] for h in history]
    my_moves = [h[0] for h in history]

    # If opponent has never cooperated, always defect.
    if all(o == 'D' for o in opp_moves):
        return 'D'

    # Check if opponent has ever retaliated to our defection.
    retaliated = False
    for i in range(1, n):
        if my_moves[i-1] == 'D' and opp_moves[i] == 'D':
            retaliated = True
            break

    if not retaliated:
        # Keep defecting to exploit unconditional cooperators.
        return 'D'

    # Cooperative mode
    # If it's the last round, defect to exploit.
    if n == 99:
        return 'D'

    # Count consecutive opponent defections from the end.
    consec_opp_def = 0
    for i in range(n - 1, -1, -1):
        if opp_moves[i] == 'D':
            consec_opp_def += 1
        else:
            break

    if consec_opp_def >= 5:
        return 'C'
    if consec_opp_def >= 2:
        return 'D'
    return 'C'
